using System;using System.Collections.Generic;using System.Collections.ObjectModel;using System.Globalization;using System.Linq;using System.Text;
namespace Frociart {
 // Read-only presentation of one real runtime frame. No expressions are evaluated.
 internal sealed class FlowVariableInspection {
  internal const int PageSize=64,PreviewLimit=160;
  internal sealed class Row {
   internal readonly long FrameId;internal readonly string Name,Type,Role,Preview;internal readonly int Kind,Group;internal readonly bool Parameter,Result;internal readonly object Value,PreviousValue;internal readonly int Change;internal string ChangeName {get{return Change==1?"Nuova":Change==2?"Modificata":"";}}internal string DisplayPreview {get{return Change==0?Preview:ChangeName+" · "+Preview;}}
   internal bool IsVector {get{return Value is VectorValue;}}internal int Count {get{return IsVector?((VectorValue)Value).Count:0;}}
   internal Row(CallFrameSnapshot frame,string name,object value,Row previous=null,bool compared=false){Change=compared?(previous==null?1:previous.Type!=frame.VariableTypes[name]||!Same(previous.Value,value)?2:0):0;PreviousValue=previous==null?null:previous.Value;FrameId=frame.FrameId;Name=name;Value=value;Type=frame.VariableTypes[name];Parameter=frame.ParameterNames.Any(p=>String.Equals(p,name,StringComparison.OrdinalIgnoreCase));Result=!String.IsNullOrEmpty(frame.ResultName)&&String.Equals(frame.ResultName,name,StringComparison.OrdinalIgnoreCase);Group=Parameter?0:Result?2:1;Role=Parameter?(Result?"Parametro · risultato":"Parametro"):Result?"Risultato":"Variabile locale";Kind=Type.StartsWith("Intero",StringComparison.Ordinal)?1:Type.StartsWith("Reale",StringComparison.Ordinal)?2:Type.StartsWith("Testo",StringComparison.Ordinal)?3:Type.StartsWith("Logico",StringComparison.Ordinal)?4:0;Preview=IsVector?"Vettore · "+Count+" elementi":Compact(ValueFormatter.Format(value));}
   internal string FullValue(){return ValueFormatter.Format(Value);}
   internal string ElementValue(int index){if(!IsVector)throw new InvalidOperationException("La variabile non è un vettore.");return ValueFormatter.Format(((VectorValue)Value).At(index));}
   internal Page<Element> Elements(int offset){if(!IsVector)throw new InvalidOperationException("La variabile non è un vettore.");int start=PageStart(offset,Count);return new Page<Element>(Enumerable.Range(start,Math.Min(PageSize,Count-start)).Select(i=>new Element(i,((VectorValue)Value).At(i))),start,Count);}
  }
  internal sealed class Element {internal readonly int Index;internal readonly object Value;internal readonly string Preview;internal Element(int index,object value){Index=index;Value=value;Preview=Compact(Values.Numeric(value)?ComparisonCell(value):ValueFormatter.Format(value));}internal string FullValue(){return ValueFormatter.Format(Value);}}
  internal sealed class Page<T> {internal readonly ReadOnlyCollection<T> Rows;internal readonly int Offset,Total;internal Page(IEnumerable<T> rows,int offset,int total){Rows=rows.ToList().AsReadOnly();Offset=offset;Total=total;}internal bool Previous {get{return Offset>0;}}internal bool Next {get{return Offset+Rows.Count<Total;}}}
  internal readonly int ComparisonStep;internal readonly long Generation;internal readonly int Steps;internal readonly RuntimeState State;internal readonly IList<CallFrameInfo> Frames;internal readonly CallFrameSnapshot Frame;internal readonly bool Fallback;internal readonly ReadOnlyCollection<Row> Rows;
  internal FlowVariableInspection(Interpreter runner,long requested=0,FlowVariableInspection previous=null){ComparisonStep=previous==null?-1:previous.Steps;var old=previous==null?null:previous.Rows.ToDictionary(r=>r.Name,StringComparer.OrdinalIgnoreCase);if(runner==null)throw new ArgumentNullException("runner");Generation=runner.Generation;Steps=runner.Steps;State=runner.State;Frames=runner.FrameInfos;Frame=runner.InspectFrame(requested);Fallback=requested!=0&&Frame==null;if(Fallback)Frame=runner.InspectFrame(0);Rows=(Frame==null?Enumerable.Empty<Row>():Frame.Variables.Select(p=>new Row(Frame,p.Key,p.Value,old!=null&&old.ContainsKey(p.Key)?old[p.Key]:null,old!=null))).OrderBy(r=>r.Group).ThenBy(r=>r.Name,StringComparer.OrdinalIgnoreCase).ToList().AsReadOnly();}
  internal Page<Row> Filter(string query,int offset=0){query=(query??"").Trim();var all=query.Length==0?Rows.ToList():Rows.Where(r=>r.Name.IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0).ToList();int start=PageStart(offset,all.Count);return new Page<Row>(all.Skip(start).Take(PageSize),start,all.Count);}
  internal Row Find(string name){return Rows.FirstOrDefault(r=>String.Equals(r.Name,name,StringComparison.OrdinalIgnoreCase));}
  internal string ExportText(){var text=new StringBuilder("Frociart · variabili della prova\n");text.Append(Frame==null?"Nessuna chiamata attiva":Frame.FunctionName).Append(" · passo ").Append(Steps.ToString(CultureInfo.InvariantCulture)).Append('\n').Append("Nome\tTipo\tRuolo\tValore\n");foreach(var row in Rows)text.Append(row.Name).Append('\t').Append(row.Type).Append('\t').Append(row.Role).Append('\t').Append(Cell(row.Value)).Append('\n');return text.ToString();}
  internal static string Cell(object value){var vector=value as VectorValue;if(vector!=null)return "["+String.Join(", ",Enumerable.Range(0,vector.Count).Select(i=>Cell(vector.At(i))))+"]";var text=value as string;if(text==null)return ValueFormatter.Format(value);var b=new StringBuilder("\"");for(int i=0;i<text.Length;i++){char c=text[i];if(c=='\\')b.Append("\\\\");else if(c=='\"')b.Append("\\\"");else if(c=='\n')b.Append("\\n");else if(c=='\r')b.Append("\\r");else if(c=='\t')b.Append("\\t");else if(Char.IsHighSurrogate(c)&&i+1<text.Length&&Char.IsLowSurrogate(text[i+1])){b.Append(c).Append(text[++i]);}else if(c<32||Char.IsSurrogate(c))b.Append("\\u").Append(((int)c).ToString("x4",CultureInfo.InvariantCulture));else b.Append(c);}return b.Append('"').ToString();}
  internal static int PageStart(int requested,int total){if(total<0)throw new ArgumentOutOfRangeException("total");return total==0?0:Math.Min(Math.Max(0,requested)/PageSize,(total-1)/PageSize)*PageSize;}
  internal static string Compact(string value){if(value.Length==0)return "(testo vuoto)";var b=new StringBuilder();int i=0;while(i<value.Length){char c=value[i];string part=c=='\n'?"\\n":c=='\r'?"\\r":c=='\t'?"\\t":c=='\0'?"\\0":Char.IsHighSurrogate(c)&&i+1<value.Length&&Char.IsLowSurrogate(value[i+1])?value.Substring(i,2):Char.IsControl(c)||Char.IsSurrogate(c)?"\\u"+((int)c).ToString("x4",CultureInfo.InvariantCulture):c.ToString();if(b.Length+part.Length>PreviewLimit)break;b.Append(part);i+=part.Length==2&&Char.IsHighSurrogate(c)?2:1;}if(i<value.Length)b.Append('…');return b.ToString();}
  internal static string ComparisonCell(object value){var vector=value as VectorValue;if(vector!=null)return "["+String.Join(", ",Enumerable.Range(0,vector.Count).Select(i=>ComparisonCell(vector.At(i))))+"]";if(Values.Numeric(value)){double number=Values.Number(value),parsed;string shown=ValueFormatter.Format(value);return Double.TryParse(shown,NumberStyles.Float,CultureInfo.InvariantCulture,out parsed)&&parsed==number?shown:number.ToString("R",CultureInfo.InvariantCulture);}return Cell(value);}
  internal static bool Same(object a,object b){if(Object.ReferenceEquals(a,b))return true;var av=a as VectorValue;var bv=b as VectorValue;if(av!=null||bv!=null){if(av==null||bv==null||av.Count!=bv.Count)return false;for(int i=0;i<av.Count;i++)if(!Same(av.At(i),bv.At(i)))return false;return true;}if(Values.Numeric(a)&&Values.Numeric(b))return Values.Number(a)==Values.Number(b);return Object.Equals(a,b);}
  internal sealed class Session {
   sealed class History {internal FlowVariableInspection Latest,Previous;internal History(FlowVariableInspection latest,FlowVariableInspection previous){Latest=latest;Previous=previous;}}
   readonly Dictionary<long,History> history=new Dictionary<long,History>();
   private Interpreter runner;private long generation,frame,visit,requested;private int step;private bool stable;private RuntimeState state;private FlowVariableInspection current;internal int Captures;
   internal int TrackedFrames {get{return history.Count;}}
   internal FlowVariableInspection Read(Interpreter value,long selected=0,bool paused=true){
    if(value==null){Clear();return null;}
    if(current!=null&&Object.ReferenceEquals(runner,value)&&generation==value.Generation&&frame==value.CurrentFrameId&&visit==value.CurrentVisit&&requested==selected&&step==value.Steps&&state==value.State&&stable==paused)return current;
    if(!Object.ReferenceEquals(runner,value)||generation!=value.Generation)history.Clear();
    var active=new HashSet<long>(value.FrameInfos.Select(f=>f.FrameId));foreach(long dead in history.Keys.Where(id=>!active.Contains(id)).ToArray())history.Remove(dead);
    long chosen=selected!=0&&active.Contains(selected)?selected:value.CurrentFrameId;History prior;history.TryGetValue(chosen,out prior);var baseline=!paused||prior==null?null:value.Steps==prior.Latest.Steps?prior.Previous:prior.Latest;
    runner=value;generation=value.Generation;frame=value.CurrentFrameId;visit=value.CurrentVisit;requested=selected;step=value.Steps;state=value.State;stable=paused;Captures++;
    current=new FlowVariableInspection(value,selected,baseline);if(paused&&current.Frame!=null)history[current.Frame.FrameId]=new History(current,baseline);return current;
   }
   internal Session Copy(){var result=new Session();result.Restore(this);return result;}
   internal void Restore(Session other){if(Object.ReferenceEquals(this,other))return;Clear();if(other==null)return;runner=other.runner;generation=other.generation;frame=other.frame;visit=other.visit;requested=other.requested;step=other.step;state=other.state;stable=other.stable;current=other.current;Captures=other.Captures;foreach(var entry in other.history)history.Add(entry.Key,new History(entry.Value.Latest,entry.Value.Previous));}
   internal void Clear(){runner=null;current=null;history.Clear();}
  }
 }
}
